# deep_update :: ({'a': {'b': 1}}, {'a': {'c': 2}})
def deep_update(a, b):
    out = dict(a)
    for k, v in b.items():
        if k in out and isinstance(out[k], dict) and isinstance(v, dict):
            out[k] = deep_update(out[k], v)
        else:
            out[k] = v
    return out

if __name__ == '__main__':
    print(deep_update(({'a': {'b': 1}}, {'a': {'c': 2}})))

